#include <iostream>
#include <thread>

void worker(std::stop_token st) {
    while (!st.stop_requested()) {   // 协作式取消：定期检查
        // 模拟工作（此处空转，主线程 join 时会请求停止）
        break;                        // 演示中直接退出循环
    }
}

int main() {
    std::jthread t(worker);   // 析构自动请求停止并 join，不会 terminate
    // t 在此析构：自动 stop + join
    std::cout << "jthread done";
}
